import * as THREE from 'three';
// Keep GPU buffers alive while moving the probes; no geometry/material churn per frame.
export function updateCable142(mesh,points,{segments=28,sides=8,radius=.0065}={}){
 let g=mesh.geometry;if(!g.userData.cable142){g.dispose();g=new THREE.BufferGeometry();const n=(segments+1)*(sides+1),positions=new Float32Array(n*3),normals=new Float32Array(n*3),uv=new Float32Array(n*2),indices=[];for(let i=0;i<=segments;i++)for(let j=0;j<=sides;j++){const a=i*(sides+1)+j;uv[a*2]=i/segments;uv[a*2+1]=j/sides;if(i<segments&&j<sides){const b=a+sides+1;indices.push(a,b,a+1,b,b+1,a+1);}}g.setAttribute('position',new THREE.BufferAttribute(positions,3).setUsage(THREE.DynamicDrawUsage));g.setAttribute('normal',new THREE.BufferAttribute(normals,3).setUsage(THREE.DynamicDrawUsage));g.setAttribute('uv',new THREE.BufferAttribute(uv,2));g.setIndex(indices);g.userData.cable142=true;mesh.geometry=g;}
 const curve=new THREE.CatmullRomCurve3(points),frames=curve.computeFrenetFrames(segments,false),p=g.attributes.position,n=g.attributes.normal,normal=new THREE.Vector3();for(let i=0;i<=segments;i++){const c=curve.getPointAt(i/segments);for(let j=0;j<=sides;j++){const a=j/sides*Math.PI*2;normal.copy(frames.normals[i]).multiplyScalar(Math.cos(a)).addScaledVector(frames.binormals[i],Math.sin(a));const k=i*(sides+1)+j;p.setXYZ(k,c.x+radius*normal.x,c.y+radius*normal.y,c.z+radius*normal.z);n.setXYZ(k,normal.x,normal.y,normal.z);}}p.needsUpdate=n.needsUpdate=true;g.computeBoundingSphere();return g;
}
